<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">  FUNCTION MUL (L, R)                                 </span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">! binary *  !</span></span>
